  if (!Array.isArray(rows)) throw new Error('Audit list did not return records.');
  const events = rows
    .filter((r: any) => r?.id)
    .sort((a: any, b: any) => new Date(b.created_date || 0).getTime() - new Date(a.created_date || 0).getTime())
